import { getBackendSrv } from '@grafana/runtime';

export function getDatabases(selectdbDS: any) {
    const response$ = getBackendSrv().fetch({
        url: '/api/ds/query',
        method: 'POST',
        data: {
            queries: [
                {
                    refId: 'getDatabases',
                    datasource: {
                        type: 'mysql',
                        uid: selectdbDS.uid,
                    },
                    rawSql: 'SHOW DATABASES',
                    format: 'table',
                },
            ],
        },
    });
    return response$;
}

